const selectHealthyApprovedCredentialHomeForUpdate = `-- name: SelectHealthyApprovedCredentialHomeForUpdate :one
SELECT e.id, e.generation_id, e.catalog_id, e.generation, e.home_ref, e.name_ref, e.provider, e.approved, e.state, e.reason_code, e.active_refs, e.first_seen_at, e.last_seen_at, e.last_full_scan_at, e.health_watermark, e.missing_watermark, e.ttl_nanoseconds, e.retention_deadline, e.created_at
FROM credential_home_catalog_entry e
JOIN credential_home_catalog c
  ON c.id = e.catalog_id AND c.generation = e.generation
WHERE c.id = $1
  AND c.workspace_id = $2
  AND c.generation = $3
  AND c.state = 'available'
  AND e.provider = $4
  AND e.approved = true
  AND e.state = 'healthy'
  AND e.health_watermark >= $5
  AND e.retention_deadline > now()
  AND NOT EXISTS (
      SELECT 1 FROM runtime_home_assignment a
      WHERE a.home_ref = e.home_ref AND a.state IN ('active', 'draining')
  )
  AND NOT EXISTS (
      SELECT 1 FROM native_rotation_operation o
      WHERE (o.current_home_ref = e.home_ref OR o.target_home_ref = e.home_ref)
        AND o.state NOT IN ('committed_retired', 'aborted_candidate_retired')
  )
ORDER BY e.home_ref
LIMIT 1
FOR UPDATE OF e SKIP LOCKED
`

type SelectHealthyApprovedCredentialHomeForUpdateParams struct {
	CatalogID                 pgtype.UUID        `json:"catalog_id"`
	WorkspaceID               pgtype.UUID        `json:"workspace_id"`
	ExpectedCatalogGeneration int64              `json:"expected_catalog_generation"`
	Provider                  string             `json:"provider"`
	HealthFreshAfter          pgtype.Timestamptz `json:"health_fresh_after"`
}

func (q *Queries) SelectHealthyApprovedCredentialHomeForUpdate(ctx context.Context, arg SelectHealthyApprovedCredentialHomeForUpdateParams) (CredentialHomeCatalogEntry, error) {
	row := q.db.QueryRow(ctx, selectHealthyApprovedCredentialHomeForUpdate,
		arg.CatalogID,
		arg.WorkspaceID,
		arg.ExpectedCatalogGeneration,
		arg.Provider,
		arg.HealthFreshAfter,
	)
	var i CredentialHomeCatalogEntry
	err := row.Scan(
		&i.ID,
		&i.GenerationID,
		&i.CatalogID,
		&i.Generation,
		&i.HomeRef,
		&i.NameRef,
		&i.Provider,
		&i.Approved,
		&i.State,
		&i.ReasonCode,
		&i.ActiveRefs,
		&i.FirstSeenAt,
		&i.LastSeenAt,
		&i.LastFullScanAt,
		&i.HealthWatermark,
		&i.MissingWatermark,
		&i.TtlNanoseconds,
		&i.RetentionDeadline,
		&i.CreatedAt,
	)
	return i, err
}

